  public function executeCargarTipos(){
  	$cod_mensaje = 0;
	$this->cliente = $this->getRequestParameter('cliente_id');
	$usuario_conectado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
	
	// CONSULTAMOS LA SUBSERIE DEL CLIENTE 
	$clienteDoc = ClientePeer::retrieveByPk($this->getRequestParameter('cliente_id'));	
	$subserie = $clienteDoc->getSubserieId();
	$this->nombre_subserie = $clienteDoc->getSubserie()->getDescripcion();
	
	// CONSULTAMOS LOS TIPOS DOCUMENTALES EXISTENTES PARA ESTE CLIENTE
	$t = new Criteria();
	$t->add(ClienteContenidoPeer::CLIENTE_ID, $this->getRequestParameter('cliente_id'));
	$ActualTiDoc = ClienteContenidoPeer::doSelect($t);
	$tiposDocumentalesExistentes = array();
	foreach($ActualTiDoc as $tipoDocAct){
		$tiposDocumentalesExistentes[] = $tipoDocAct->getTipodocumentalId();
		$cod_mensaje = 1;
	}

	// CONSULTAMOS LOS TIPOS DOCUMENTALES QUE FALTAN POR CARGAR
	$c = new Criteria();
	$c->add(TipoDocumentalPeer::SUBSERIE_ID, $subserie);
	$c->add(TipoDocumentalPeer::TIPODOCUMENTAL_ID, $tiposDocumentalesExistentes, Criteria::NOT_IN);
	$tiposDocumentales = TipoDocumentalPeer::doSelect($c);
	
	foreach($tiposDocumentales as $tipoDocumental){
		$contenido_cliente = new ClienteContenido();
		$contenido_cliente->setUsuarioId($usuario_conectado);
		$contenido_cliente->setVerificacioncontclienteId(2);
		$contenido_cliente->setTipodocumentalId($tipoDocumental->getTipodocumentalId());
		$contenido_cliente->setClienteId($this->getRequestParameter('cliente_id'));				
		$contenido_cliente->setClEstadoContenidoId(2);		
		$contenido_cliente->setDescripcion('Pendiente');
		$contenido_cliente->setRuta('');
		$contenido_cliente->setFechaCreacion(date('Y-m-d G:i:s'));
		$contenido_cliente->setFolios('');
		$contenido_cliente->setCreadoPorWeb('1');
		$contenido_cliente->save();
		$cod_mensaje=2;
	}	
	if($cod_mensaje == 1){
		$this->mensaje = "No Existen Tipos Documentales Pendientes";
	}elseif($cod_mensaje == 2){
		$this->mensaje = "Se Cargaron los Tipos Documentales Exitosamente.";
	}else{
		$this->mensaje = "No se pueden Cargar los Tipos Documentales.";
	}
  }
  public function executeUpdate()
  {
    if (!$this->getRequestParameter('cliente_contenido_id'))
    {
      $cliente_contenido = new ClienteContenido();
      $cliente_contenido->setFechaCreacion(date("Y-m-d G:i:s"));
      $old_files = false;
      $txt_oldfiles = "";
    }
    else
    {
      $cliente_contenido = ClienteContenidoPeer::retrieveByPk($this->getRequestParameter('cliente_contenido_id'));
      $old_files = true;
      $txt_oldfiles = $cliente_contenido->getRuta();
      $this->forward404Unless($cliente_contenido);
    }
    //**********************************************************************************************
    //$cliente_contenido->setClienteContenidoId($this->getRequestParameter('cliente_contenido_id'));
    $usuariologeado  = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
    $cliente_contenido->setUsuarioId($usuariologeado);    
    $cliente_contenido->setVerificacioncontclienteId($this->getRequestParameter('verificacioncontcliente_id'));    
    $cliente_contenido->setTipodocumentalId($this->getRequestParameter('tipo_documental_id'));    
    $cliente_contenido->setClienteId($this->getRequestParameter('cliente_id'));    
    $cliente_contenido->setClEstadoContenidoId($this->getRequestParameter('cl_estado_contenido_id'));    
    $cliente_contenido->setDescripcion($this->getRequestParameter('descripcion'));
    $cliente_contenido->setFolios($this->getRequestParameter('folios'));    
    $cliente_contenido->setCreadoPorWeb(true);    
    //**********************************************************************************************
    $str_files = trim($this->getRequestParameter('archivo'));
    $cliente_contenido->setRuta($this->resolveUrlAttachment($str_files,$old_files,$txt_oldfiles));
    //**********************************************************************************************
    $cliente_contenido->save();
    //**********************************************************************************************
    return $this->redirect($this->getRequest()->getScriptName().'/cliente_contenido/show?cliente_contenido_id='.$cliente_contenido->getPrimaryKey());
  }    
  
